/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { distinctUntilChanged, map, Observable } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { UserInfo } from '@shared/context/identity/user-info.model';

/** Un permiso se concede si el usuario autenticado lo tiene entre sus `permissions` o sus `roles`. */
export function grants(user: UserInfo | null | undefined, perm: string): boolean {
  if (!user?.authenticated) {
    return false;
  }
  return (user.permissions ?? []).includes(perm) || (user.roles ?? []).includes(perm);
}

@Injectable({ providedIn: 'root' })
export class PermissionService {
  private readonly state = inject(AppStateService);

  /** Emite si el usuario de `identity` tiene `perm`, y vuelve a emitir solo cuando cambia. */
  has(perm: string, identity = 'main'): Observable<boolean> {
    return this.state.userInfo[identity].pipe(
      map((user) => grants(user, perm)),
      distinctUntilChanged(),
    );
  }
}
